/* Habit Tracker — app logic.
   The list of habits lives in one localStorage key; the page is only a view of it. */

(function () {
  "use strict";

  var STORAGE_KEY = "habit-tracker.habits.v1";
  var MAX_NAME_LENGTH = 60;
  var DATE_KEY = /^\d{4}-\d{2}-\d{2}$/;
  var SVG_NS = "http://www.w3.org/2000/svg";

  var els = {};
  var habits = [];

  /* ---------- date helpers ---------- */

  function pad(value) {
    return value < 10 ? "0" + value : String(value);


  function dateKey(date) {
    return date.getFullYear() + "-" + pad(date.getMonth() + 1) + "-" + pad(date.getDate());
  }

  function todayKey() {
    return dateKey(new Date());
  }

  function keyToDate(key) {
    var parts = key.split("-");
    return new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
  }

  function isDateKey(value) {
    if (typeof value !== "string" || !DATE_KEY.test(value)) return false;
    var date = keyToDate(value);
    return !isNaN(date.getTime()) && dateKey(date) === value;
  }

  function formatDate(key) {
    var date = keyToDate(key);
    if (isNaN(date.getTime())) return "";
    return date.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" });
  }

  function lastTickedLabel(days) {
    if (days === 0) return "No streak yet";
    if (days === 1) return "1 day streak";
    return days + " day streak";
  }

  function totalLabel(count) {
    if (count === 1) return "1 day ticked";
    return count + " days ticked";
  }

  function bestStreakLabel(days) {
    if (days === 0) return "0 days";
    if (days === 1) return "1 day";
    return days + " days";
  }

  /* ---------- storage ---------- */

  function makeId() {
    if (window.crypto && typeof window.crypto.randomUUID === "function") {
      return window.crypto.randomUUID();
    }
    return "h" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function cleanHabit(entry) {
    if (!entry || typeof entry !== "object") return null;

    var name = typeof entry.name === "string" ? entry.name.trim().slice(0, MAX_NAME_LENGTH) : "";
    if (!name) return null;

    var id = typeof entry.id === "string" && entry.id ? entry.id : makeId();
    var created = isDateKey(entry.created) ? entry.created : todayKey();
    var ticks = [];

    if (Array.isArray(entry.ticks)) {
      entry.ticks.forEach(function (tick) {
        if (isDateKey(tick) && ticks.indexOf(tick) === -1) ticks.push(tick);
      });
    }

    ticks.sort();

    return { id: id, name: name, created: created, ticks: ticks };
  }

  function loadHabits() {
    var raw;
    try {
      raw = window.localStorage.getItem(STORAGE_KEY);
    } catch (err) {
      return [];
    }
    if (!raw) return [];

    var parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (err) {
      return [];
    }
    if (!Array.isArray(parsed)) return [];

    var cleaned = [];
    parsed.forEach(function (entry) {
      var habit = cleanHabit(entry);
      if (habit) cleaned.push(habit);
    });
    return cleaned;
  }

  function saveHabits() {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(habits));
    } catch (err) {
      // Storage may be full or blocked; the page keeps working for this session.
    }
  }

  /* ---------- streak maths ---------- */

  function currentStreak(ticks) {
    if (!ticks || ticks.length === 0) return 0;

    var ticked = {};
    ticks.forEach(function (tick) {
      ticked[tick] = true;
    });

    var cursor = new Date();
    if (!ticked[dateKey(cursor)]) {
      // A streak survives until the end of today, so a tick yesterday still counts.
      cursor.setDate(cursor.getDate() - 1);
      if (!ticked[dateKey(cursor)]) return 0;
    }

    var streak = 0;
    while (ticked[dateKey(cursor)]) {
      streak += 1;
      cursor.setDate(cursor.getDate() - 1);
    }
    return streak;
  }

  /* ---------- elements ---------- */

  function makeIcon(pathData) {
    var svg = document.createElementNS(SVG_NS, "svg");
    svg.setAttribute("class", "icon");
    svg.setAttribute("width", "16");
    svg.setAttribute("height", "16");
    svg.setAttribute("viewBox", "0 0 16 16");
    svg.setAttribute("aria-hidden", "true");
    svg.setAttribute("focusable", "false");

    var path = document.createElementNS(SVG_NS, "path");
    path.setAttribute("d", pathData);
    path.setAttribute("fill", "none");
    path.setAttribute("stroke", "currentColor");
    path.setAttribute("stroke-width", "1.75");
    path.setAttribute("stroke-linecap", "round");
    path.setAttribute("stroke-linejoin", "round");

    svg.appendChild(path);
    return svg;
  }

  function buildHabitItem(habit, today) {
    var tickedToday = habit.ticks.indexOf(today) !== -1;
    var streak = currentStreak(habit.ticks);

    var item = document.createElement("li");
    item.className = "habit-item" + (tickedToday ? " is-ticked" : "");
    item.dataset.id = habit.id;

    var info = document.createElement("div");
    info.className = "habit-info";

    var name = document.createElement("p");
    name.className = "habit-name";
    name.textContent = habit.name;
    info.appendChild(name);

    var meta = document.createElement("p");
    meta.className = "habit-meta";
    meta.textContent = totalLabel(habit.ticks.length) + " \u00b7 Added " + formatDate(habit.created);
    info.appendChild(meta);

    var side = document.createElement("div");
    side.className = "habit-side";

    var streakNote = document.createElement("p");
    streakNote.className = "habit-streak";
    streakNote.textContent = lastTickedLabel(streak);
    side.appendChild(streakNote);

    var actions = document.createElement("div");
    actions.className = "habit-actions";

    var tickButton = document.createElement("button");
    tickButton.type = "button";
    tickButton.className = "btn tick-btn";
    tickButton.dataset.action = "tick";
    tickButton.setAttribute("aria-pressed", tickedToday ? "true" : "false");
    tickButton.setAttribute(
      "aria-label",
      (tickedToday ? "Untick " : "Tick ") + habit.name + " for today"
    );
    tickButton.appendChild(makeIcon("M3.25 8.25l3.25 3.25 6.25-7"));
    var tickText = document.createElement("span");
    tickText.textContent = tickedToday ? "Ticked" : "Tick today";
    tickButton.appendChild(tickText);
    actions.appendChild(tickButton);

    var deleteButton = document.createElement("button");
    deleteButton.type = "button";
    deleteButton.className = "btn btn-quiet delete-btn";
    deleteButton.dataset.action = "delete";
    deleteButton.setAttribute("aria-label", "Delete " + habit.name);
    deleteButton.appendChild(makeIcon("M3.5 4.75h9M6.5 4.75V3.5h3v1.25M4.75 4.75l.5 8h5.5l.5-8"));
    actions.appendChild(deleteButton);

    side.appendChild(actions);
    item.appendChild(info);
    item.appendChild(side);

    return item;
  }

  function render() {
    var today = todayKey();

    els.list.textContent = "";
    habits.forEach(function (habit) {
      els.list.appendChild(buildHabitItem(habit, today));
    });

    els.empty.hidden = habits.length > 0;

    var tickedToday = habits.filter(function (habit) {
      return habit.ticks.indexOf(today) !== -1;
    }).length;

    var best = habits.reduce(function (max, habit) {
      return Math.max(max, currentStreak(habit.ticks));
    }, 0);

    els.summaryCount.textContent = String(habits.length);
    els.summaryToday.textContent = String(tickedToday);
    els.summaryStreak.textContent = bestStreakLabel(best);
  }

  /* ---------- actions ---------- */

  function addHabit(rawName) {
    var name = typeof rawName === "string" ? rawName.trim().slice(0, MAX_NAME_LENGTH) : "";
    if (!name) return false;

    habits.push({ id: makeId(), name: name, created: todayKey(), ticks: [] });
    saveHabits();
    render();
    return true;
  }

  function toggleTick(id) {
    var today = todayKey();
    var changed = false;

    habits = habits.map(function (habit) {
      if (habit.id !== id) return habit;

      changed = true;
      var ticks = habit.ticks.slice();
      var at = ticks.indexOf(today);

      if (at === -1) {
        ticks.push(today);
        ticks.sort();
      } else {
        ticks.splice(at, 1);
      }

      return { id: habit.id, name: habit.name, created: habit.created, ticks: ticks };
    });

    if (changed) {
      saveHabits();
      render();
    }
  }

  function deleteHabit(id) {
    var before = habits.length;
    habits = habits.filter(function (habit) {
      return habit.id !== id;
    });

    if (habits.length !== before) {
      saveHabits();
      render();
    }
  }

  /* ---------- wiring ---------- */

  function onListClick(event) {
    var button = event.target.closest("button[data-action]");
    if (!button) return;

    var item = button.closest(".habit-item");
    if (!item || !item.dataset.id) return;

    if (button.dataset.action === "tick") {
      toggleTick(item.dataset.id);
      // Keep the keyboard where the person was working.
      focusTickButton(item.dataset.id);
    } else if (button.dataset.action === "delete") {
      deleteHabit(item.dataset.id);
    }
  }

  function focusTickButton(id) {
    var item = els.list.querySelector('.habit-item[data-id="' + id + '"]');
    if (!item) return;
    var button = item.querySelector("button[data-action='tick']");
    if (button) button.focus();
  }

  function onSubmit(event) {
    event.preventDefault();

    var added = addHabit(els.input.value);
    if (added) {
      els.input.value = "";
      els.input.focus();
    }
  }

  function onStorage(event) {
    if (event.key !== null && event.key !== STORAGE_KEY) return;
    habits = loadHabits();
    render();
  }

  function start() {
    els.form = document.getElementById("habit-form-box");
    els.input = document.getElementById("habit-name");
    els.list = document.getElementById("habit-list");
    els.empty = document.getElementById("habit-empty");
    els.summaryCount = document.getElementById("summary-count");
    els.summaryToday = document.getElementById("summary-today");
    els.summaryStreak = document.getElementById("summary-streak");

    if (!els.form || !els.input || !els.list || !els.empty) return;

    habits = loadHabits();
    render();

    els.form.addEventListener("submit", onSubmit);
    els.list.addEventListener("click", onListClick);
    window.addEventListener("storage", onStorage);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();

