/* Habit Tracker — styles.
   One calm palette, one accent colour, everything drawn with CSS. */

/* ---------- tokens ---------- */

:root {
  --bg: #f5f6f3;
  --surface: #ffffff;
  --surface-alt: #f1f3ef;
  --item-bg: #fafbf9;
  --ink: #1b211e;
  --ink-soft: #5d675f;
  --line: #e3e7e0;
  --accent: #2f7d5c;
  --accent-strong: #24634a;
  --accent-soft: #e7f3ec;
  --accent-border: #cfe6da;
  --accent-ring: rgba(47, 125, 92, 0.35);
  --on-accent: #ffffff;
  --shadow: 0 1px 2px rgba(20, 30, 25, 0.05), 0 6px 20px -12px rgba(20, 30, 25, 0.25);
  --radius: 0.85rem;
  --font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #141816;
    --surface: #1b211e;
    --surface-alt: #232b27;
    --item-bg: #202824;
    --ink: #eef2ee;
    --ink-soft: #a3ada6;
    --line: #2d362f;
    --accent: #4fb98a;
    --accent-strong: #7fd3ab;
    --accent-soft: #1f3a2e;
    --accent-border: #2f5c48;
    --accent-ring: rgba(79, 185, 138, 0.4);
    --on-accent: #0d1512;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.4), 0 6px 20px -12px rgba(0, 0, 0, 0.7);
  }
}

/* ---------- base ---------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
p,
ul,
dl,
dt,
dd {
  margin: 0;
}

svg.icon {
  display: block;
  width: 1rem;
  height: 1rem;
  flex: none;
}

/* ---------- layout ---------- */

.wrap {
  width: 100%;
  max-width: 60rem;
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 2rem);
}

.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}

.site-header .wrap {
  padding-block: clamp(1.4rem, 4vw, 2.4rem);
}

main.wrap {
  flex: 1 0 auto;
  display: grid;
  gap: clamp(1rem, 2.5vw, 1.5rem);
  padding-block: clamp(1.25rem, 3vw, 2rem);
  align-content: start;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 1rem;
  padding: clamp(1rem, 2.5vw, 1.5rem);
  box-shadow: var(--shadow);
}

.site-footer {
  border-top: 1px solid var(--line);
  color: var(--ink-soft);
  font-size: 0.85rem;
}

.site-footer .wrap {
  padding-block: clamp(1rem, 3vw, 1.6rem);
}

.site-footer p {
  max-width: 60ch;
}

/* ---------- skip link ---------- */

.skip-link {
  position: absolute;
  left: 1rem;
  top: -4rem;
  z-index: 20;
  padding: 0.65rem 1rem;
  border-radius: 0.6rem;
  background: var(--ink);
  color: var(--surface);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 600;
  transition: top 0.15s ease;
}

.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--accent-ring);
  outline-offset: 2px;
}

/* ---------- headings ---------- */

.app-name {
  font-size: clamp(1.6rem, 1.25rem + 1.8vw, 2.15rem);
  font-weight: 680;
  letter-spacing: -0.015em;
  line-height: 1.15;
}

.tagline {
  margin-top: 0.4rem;
  max-width: 46ch;
  color: var(--ink-soft);
  font-size: clamp(0.9rem, 0.86rem + 0.25vw, 1rem);
}

.panel h2 {
  font-size: 1.05rem;
  font-weight: 650;
  letter-spacing: 0.005em;
  margin-bottom: 0.9rem;
}

/* ---------- add-habit form ---------- */

.field-label {
  display: block;
  margin-bottom: 0.4rem;
  font-size: 0.9rem;
  font-weight: 600;
}

.field-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}

.field-input {
  flex: 1 1 14rem;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.7rem 0.85rem;
  font: inherit;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 0.65rem;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field-input:hover {
  border-color: var(--ink-soft);
}

.field-input:focus-visible {
  outline: 3px solid var(--accent-ring);
  outline-offset: 1px;
  border-color: var(--accent);
}

.field-hint {
  margin-top: 0.6rem;
  font-size: 0.82rem;
  color: var(--ink-soft);
}

/* ---------- buttons ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  min-height: 2.75rem;
  padding: 0.55rem 0.95rem;
  font: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.2;
  border: 1px solid transparent;
  border-radius: 0.65rem;
  background: var(--accent);
  color: var(--on-accent);
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, transform 0.08s ease;
}

.btn:hover {
  background: var(--accent-strong);
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible {
  outline: 3px solid var(--accent-ring);
  outline-offset: 2px;
}

/* tick button: outlined until the day is ticked, then filled */

.tick-btn {
  background: var(--surface);
  color: var(--accent-strong);
  border-color: var(--accent);
}

.tick-btn:hover {
  background: var(--accent-soft);
}

.tick-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--on-accent);
}

.tick-btn[aria-pressed="true"]:hover {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

/* quiet icon-only button used for delete */

.btn-quiet {
  width: 2.75rem;
  padding: 0.5rem;
  background: transparent;
  border-color: transparent;
  color: var(--ink-soft);
}

.btn-quiet:hover {
  background: var(--surface-alt);
  color: var(--ink);
}

/* ---------- habit list ---------- */

.habit-list {
  list-style: none;
  padding: 0;
  display: grid;
  gap: 0.7rem;
}

.habit-item {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.9rem;
  padding: 0.85rem 1rem;
  background: var(--item-bg);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  transition: background-color 0.18s ease, border-color 0.18s ease;
}

.habit-item.is-ticked {
  background: var(--accent-soft);
  border-color: var(--accent-border);
}

.habit-info {
  flex: 1 1 auto;
  min-width: 0;
}

.habit-name {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.habit-meta {
  margin-top: 0.2rem;
  font-size: 0.8rem;
  color: var(--ink-soft);
}

.habit-side {
  flex: none;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.5rem;
}

.habit-streak {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink-soft);
  white-space: nowrap;
}

.habit-item.is-ticked .habit-streak {
  color: var(--accent-strong);
}

.habit-actions {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

/* ---------- empty note ---------- */

.empty-note {
  margin-top: 0.2rem;
  padding: 1.1rem 1rem;
  text-align: center;
  color: var(--ink-soft);
  font-size: 0.9rem;
  background: var(--surface-alt);
  border: 1px dashed var(--line);
  border-radius: var(--radius);
}

.empty-note[hidden] {
  display: none;
}

/* ---------- streak summary ---------- */

.summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8.5rem, 1fr));
  gap: 0.7rem;
}

.summary-item {
  padding: 0.8rem 0.9rem;
  background: var(--surface-alt);
  border-radius: 0.75rem;
}

.summary-item dt {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--ink-soft);
}

.summary-item dd {
  margin-top: 0.15rem;
  font-size: 1.35rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}

/* ---------- narrow phones ---------- */

@media (max-width: 34rem) {
  .habit-item {
    flex-direction: column;
    align-items: stretch;
  }

  .habit-side {
    width: 100%;
    align-items: stretch;
  }

  .habit-streak {
    text-align: left;
    white-space: normal;
  }

  .tick-btn {
    flex: 1 1 auto;
  }

  .field-row .btn {
    width: 100%;
  }
}

@media (max-width: 26rem) {
  .summary {
    grid-template-columns: 1fr 1fr;
  }

  .summary-item:last-child {
    grid-column: 1 / -1;
  }
}

/* ---------- motion preferences ---------- */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }

  .btn:active {
    transform: none;
  }
}

/* Habit Tracker — app logic.
   The habits live in one localStorage key; the page is only a view of that state.
   The light/dark choice lives in a second key of its own. */

(function () {
  "use strict";

  var STORAGE_KEY = "habit-tracker.habits.v1";
  var THEME_KEY = "habit-tracker.theme.v1";
  var MAX_NAME_LENGTH = 60;
  var DATE_KEY = /^\d{4}-\d{2}-\d{2}$/;
  var SVG_NS = "http://www.w3.org/2000/svg";

  var els = {};
  var habits = [];

  /* ---------- date helpers ---------- */

  function pad(value) {
    return value < 10 ? "0" + value : String(value);
  }

  function dateKey(date) {
    return date.getFullYear() + "-" + pad(date.getMonth() + 1) + "-" + pad(date.getDate());
  }

  function todayKey() {
    return dateKey(new Date());
  }

  function keyToDate(key) {
    var parts = key.split("-");
    return new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
  }

  function isDateKey(value) {
    if (typeof value !== "string" || !DATE_KEY.test(value)) return false;
    var date = keyToDate(value);
    return !isNaN(date.getTime()) && dateKey(date) === value;
  }

  function formatDate(key) {
    if (!isDateKey(key)) return "";
    return keyToDate(key).toLocaleDateString(undefined, {
      day: "numeric",
      month: "short",
      year: "numeric"
    });
  }

  /* ---------- small labels ---------- */

  function streakLabel(days) {
    if (days === 0) return "No streak yet";
    if (days === 1) return "1 day streak";
    return days + " day streak";
  }

  function tickedLabel(count) {
    if (count === 0) return "Not ticked yet";
    if (count === 1) return "1 day ticked";
    return count + " days ticked";
  }

  function bestStreakLabel(days) {
    if (days === 1) return "1 day";
    return days + " days";
  }

  /* ---------- storage ---------- */

  function makeId() {
    if (window.crypto && typeof window.crypto.randomUUID === "function") {
      return window.crypto.randomUUID();
    }
    return "h" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function cleanHabit(entry) {
    if (!entry || typeof entry !== "object") return null;

    var name = typeof entry.name === "string" ? entry.name.trim().slice(0, MAX_NAME_LENGTH) : "";
    if (!name) return null;

    var id = typeof entry.id === "string" && entry.id ? entry.id : makeId();
    var created = isDateKey(entry.created) ? entry.created : todayKey();
    var ticks = [];

    if (Array.isArray(entry.ticks)) {
      entry.ticks.forEach(function (tick) {
        if (isDateKey(tick) && ticks.indexOf(tick) === -1) ticks.push(tick);
      });
    }

    ticks.sort();

    return { id: id, name: name, created: created, ticks: ticks };
  }

  function loadHabits() {
    var raw;
    try {
      raw = window.localStorage.getItem(STORAGE_KEY);
    } catch (err) {
      return [];
    }
    if (!raw) return [];

    var parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (err) {
      return [];
    }
    if (!Array.isArray(parsed)) return [];

    var cleaned = [];
    parsed.forEach(function (entry) {
      var habit = cleanHabit(entry);
      if (habit) cleaned.push(habit);
    });
    return cleaned;
  }

  function saveHabits() {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(habits));
    } catch (err) {
      /* Storage can be full or blocked; the page keeps working for this session. */
    }
  }

  /* ---------- streak maths ---------- */

  function currentStreak(ticks, today) {
    if (!ticks || ticks.length === 0) return 0;

    var ticked = {};
    ticks.forEach(function (tick) {
      ticked[tick] = true;
    });

    var cursor = keyToDate(today);

    // A streak is not broken until today ends, so a tick yesterday still counts.
    if (!ticked[today]) {
      cursor.setDate(cursor.getDate() - 1);
      if (!ticked[dateKey(cursor)]) return 0;
    }

    var streak = 0;
    while (ticked[dateKey(cursor)]) {
      streak += 1;
      cursor.setDate(cursor.getDate() - 1);
    }
    return streak;
  }

  /* ---------- theme ---------- */

  function validTheme(value) {
    return value === "dark" ? "dark" : "light";
  }

  function loadTheme() {
    var stored = null;
    try {
      stored = window.localStorage.getItem(THEME_KEY);
    } catch (err) {
      stored = null;
    }
    if (stored === "light" || stored === "dark") return stored;

    // Nothing saved yet: stay with the theme the page shipped with.
    return validTheme(document.documentElement.dataset.theme);
  }

  function saveTheme(theme) {
    try {
      window.localStorage.setItem(THEME_KEY, theme);
    } catch (err) {
      /* Same as above: the choice holds for this session even if it cannot be stored. */
    }
  }

  function applyTheme(theme) {
    var next = validTheme(theme);
    document.documentElement.dataset.theme = next;

    if (!els.themeToggle) return;

    // The label names the setting ("Dark mode"); aria-pressed reports whether it is on.
    els.themeToggle.setAttribute("aria-pressed", next === "dark" ? "true" : "false");
  }

  function toggleTheme() {
    var next = document.documentElement.dataset.theme === "dark" ? "light" : "dark";
    applyTheme(next);
    saveTheme(next);
  }

  /* ---------- building the view ---------- */

  function makeIcon(pathData) {
    var svg = document.createElementNS(SVG_NS, "svg");
    svg.setAttribute("class", "icon");
    svg.setAttribute("width", "16");
    svg.setAttribute("height", "16");
    svg.setAttribute("viewBox", "0 0 16 16");
    svg.setAttribute("aria-hidden", "true");
    svg.setAttribute("focusable", "false");

    var path = document.createElementNS(SVG_NS, "path");
    path.setAttribute("d", pathData);
    path.setAttribute("fill", "none");
    path.setAttribute("stroke", "currentColor");
    path.setAttribute("stroke-width", "1.75");
    path.setAttribute("stroke-linecap", "round");
    path.setAttribute("stroke-linejoin", "round");

    svg.appendChild(path);
    return svg;
  }

  function buildHabitItem(habit, today) {
    var tickedToday = habit.ticks.indexOf(today) !== -1;
    var streak = currentStreak(habit.ticks, today);

    var item = document.createElement("li");
    item.className = "habit-item" + (tickedToday ? " is-ticked" : "");
    item.dataset.id = habit.id;

    var info = document.createElement("div");
    info.className = "habit-info";

    var name = document.createElement("p");
    name.className = "habit-name";
    name.textContent = habit.name;
    info.appendChild(name);

    var meta = document.createElement("p");
    meta.className = "habit-meta";
    meta.textContent = tickedLabel(habit.ticks.length) + " \u00b7 added " + formatDate(habit.created);
    info.appendChild(meta);

    var side = document.createElement("div");
    side.className = "habit-side";

    var streakNote = document.createElement("p");
    streakNote.className = "habit-streak";
    streakNote.textContent = streakLabel(streak);
    side.appendChild(streakNote);

    var actions = document.createElement("div");
    actions.className = "habit-actions";

    var tickButton = document.createElement("button");
    tickButton.type = "button";
    tickButton.className = "btn tick-btn";
    tickButton.dataset.action = "tick";
    tickButton.setAttribute("aria-pressed", tickedToday ? "true" : "false");
    tickButton.setAttribute(
      "aria-label",
      (tickedToday ? "Untick " : "Tick ") + habit.name + " for today"
    );
    tickButton.appendChild(makeIcon("M3.25 8.25l3.25 3.25 6.25-7"));

    var tickText = document.createElement("span");
    tickText.textContent = tickedToday ? "Ticked" : "Tick today";
    tickButton.appendChild(tickText);
    actions.appendChild(tickButton);

    var deleteButton = document.createElement("button");
    deleteButton.type = "button";
    deleteButton.className = "btn btn-quiet delete-btn";
    deleteButton.dataset.action = "delete";
    deleteButton.setAttribute("aria-label", "Delete " + habit.name);
    deleteButton.appendChild(
      makeIcon("M3.5 4.75h9M6.5 4.75V3.5h3v1.25M4.75 4.75l.5 8h5.5l.5-8")
    );
    actions.appendChild(deleteButton);

    side.appendChild(actions);
    item.appendChild(info);
    item.appendChild(side);

    return item;
  }

  function render() {
    var today = todayKey();

    els.list.textContent = "";
    habits.forEach(function (habit) {
      els.list.appendChild(buildHabitItem(habit, today));
    });

    els.empty.hidden = habits.length > 0;

    var tickedToday = habits.filter(function (habit) {
      return habit.ticks.indexOf(today) !== -1;
    }).length;

    var best = habits.reduce(function (max, habit) {
      return Math.max(max, currentStreak(habit.ticks, today));
    }, 0);

    if (els.summaryCount) els.summaryCount.textContent = String(habits.length);
    if (els.summaryToday) els.summaryToday.textContent = String(tickedToday);
    if (els.summaryStreak) els.summaryStreak.textContent = bestStreakLabel(best);
  }

  /* ---------- actions ---------- */

  function addHabit(rawName) {
    var name = typeof rawName === "string" ? rawName.trim().slice(0, MAX_NAME_LENGTH) : "";
    if (!name) return false;

    habits.push({ id: makeId(), name: name, created: todayKey(), ticks: [] });
    saveHabits();
    render();
    return true;
  }

  function toggleTick(id) {
    var today = todayKey();
    var changed = false;

    habits = habits.map(function (habit) {
      if (habit.id !== id) return habit;

      changed = true;
      var ticks = habit.ticks.slice();
      var at = ticks.indexOf(today);

      if (at === -1) {
        ticks.push(today);
        ticks.sort();
      } else {
        ticks.splice(at, 1);
      }

      return { id: habit.id, name: habit.name, created: habit.created, ticks: ticks };
    });

    if (changed) {
      saveHabits();
      render();
    }
  }

  function deleteHabit(id) {
    var before = habits.length;
    habits = habits.filter(function (habit) {
      return habit.id !== id;
    });

    if (habits.length !== before) {
      saveHabits();
      render();
    }
  }

  /* ---------- wiring ---------- */

  function focusTickButton(id) {
    var item = els.list.querySelector('.habit-item[data-id="' + id + '"]');
    if (!item) return;
    var button = item.querySelector('button[data-action="tick"]');
    if (button) button.focus();
  }

  function onListClick(event) {
    var target = event.target;
    if (!target || typeof target.closest !== "function") return;

    var button = target.closest("button[data-action]");
    if (!button) return;

    var item = button.closest(".habit-item");
    if (!item || !item.dataset.id) return;

    if (button.dataset.action === "tick") {
      var id = item.dataset.id;
      toggleTick(id);
      // Keep the keyboard where the person was working.
      focusTickButton(id);
    } else if (button.dataset.action === "delete") {
      deleteHabit(item.dataset.id);
    }
  }

  function onSubmit(event) {
    event.preventDefault();

    if (addHabit(els.input.value)) {
      els.input.value = "";
    }
    els.input.focus();
  }

  function onStorage(event) {
    if (event.key === STORAGE_KEY) {
      habits = loadHabits();
      render();
    } else if (event.key === THEME_KEY) {
      applyTheme(validTheme(event.newValue));
    }
  }

  function start() {
    els.form = document.getElementById("habit-form");
    els.input = document.getElementById("habit-name");
    els.list = document.getElementById("habit-list");
    els.empty = document.getElementById("habit-empty");
    els.summaryCount = document.getElementById("summary-count");
    els.summaryToday = document.getElementById("summary-today");
    els.summaryStreak = document.getElementById("summary-streak");
    els.themeToggle = document.getElementById("theme-toggle");

    // The saved choice wins; the page stays with its own theme until one is saved.
    applyTheme(loadTheme());

    if (els.themeToggle) {
      els.themeToggle.addEventListener("click", toggleTheme);
    }

    if (!els.form || !els.input || !els.list || !els.empty) return;

    habits = loadHabits();
    render();

    els.form.addEventListener("submit", onSubmit);
    els.list.addEventListener("click", onListClick);
    window.addEventListener("storage", onStorage);
  }

  // Set the theme before first paint, then wire everything up once the page is ready.
  applyTheme(loadTheme());

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();

/* Habit Tracker — styles.
   One calm palette, one accent colour, everything drawn with CSS.
   Light and dark come from data-theme on <html>, which app.js keeps in step. */

/* ---------- tokens ---------- */

:root {
  color-scheme: light;

  --bg: #f5f6f3;
  --surface: #ffffff;
  --surface-alt: #f1f3ef;
  --item-bg: #fafbf9;
  --ink: #1b211e;
  --ink-soft: #5d675f;
  --line: #e3e7e0;
  --accent: #2f7d5c;
  --accent-strong: #24634a;
  --accent-soft: #e7f3ec;
  --accent-border: #cfe6da;
  --accent-ring: rgba(47, 125, 92, 0.35);
  --on-accent: #ffffff;
  --danger: #a8412f;
  --danger-soft: #f7e9e5;
  --shadow: 0 1px 2px rgba(20, 30, 25, 0.05), 0 6px 20px -12px rgba(20, 30, 25, 0.25);
  --radius: 0.85rem;
  --font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

/* The saved choice on <html> is the single source of truth for the theme. */

html[data-theme="dark"] {
  color-scheme: dark;

  --bg: #141816;
  --surface: #1b211e;
  --surface-alt: #232b27;
  --item-bg: #202824;
  --ink: #eef2ee;
  --ink-soft: #a3ada6;
  --line: #2d362f;
  --accent: #4fb98a;
  --accent-strong: #7fd3ab;
  --accent-soft: #1f3a2e;
  --accent-border: #2f5c48;
  --accent-ring: rgba(79, 185, 138, 0.45);
  --on-accent: #0d1512;
  --danger: #e0897a;
  --danger-soft: #3a2520;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.4), 0 6px 20px -12px rgba(0, 0, 0, 0.7);
}

/* ---------- base ---------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  transition: background-color 0.2s ease, color 0.2s ease;
}

h1,
h2,
p,
ul,
dl,
dt,
dd {
  margin: 0;
}

svg.icon {
  display: block;
  width: 1rem;
  height: 1rem;
  flex: none;
}

/* ---------- layout ---------- */

.wrap {
  width: 100%;
  max-width: 60rem;
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 2rem);
}

.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}

.site-header .wrap {
  padding-block: clamp(1.4rem, 4vw, 2.4rem);
}

.header-inner {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem 1.5rem;
}

.header-text {
  min-width: 0;
  flex: 1 1 16rem;
}

main.wrap {
  flex: 1 0 auto;
  display: grid;
  gap: clamp(1rem, 2.5vw, 1.5rem);
  padding-block: clamp(1.25rem, 3vw, 2rem);
  align-content: start;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 1rem;
  padding: clamp(1rem, 2.5vw, 1.5rem);
  box-shadow: var(--shadow);
}

.site-footer {
  border-top: 1px solid var(--line);
  color: var(--ink-soft);
  font-size: 0.85rem;
}

.site-footer .wrap {
  padding-block: clamp(1rem, 3vw, 1.6rem);
}

.site-footer p {
  max-width: 60ch;
}

#main-content {
  scroll-margin-top: 1rem;
}

/* ---------- skip link ---------- */

.skip-link {
  position: absolute;
  left: 1rem;
  top: -4rem;
  z-index: 20;
  padding: 0.65rem 1rem;
  border-radius: 0.6rem;
  background: var(--ink);
  color: var(--surface);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 600;
  transition: top 0.15s ease;
}

.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--accent-ring);
  outline-offset: 2px;
}

/* ---------- headings ---------- */

.app-name {
  font-size: clamp(1.6rem, 1.25rem + 1.8vw, 2.15rem);
  font-weight: 680;
  letter-spacing: -0.015em;
  line-height: 1.15;
}

.tagline {
  margin-top: 0.4rem;
  max-width: 46ch;
  color: var(--ink-soft);
  font-size: clamp(0.9rem, 0.86rem + 0.25vw, 1rem);
}

.panel h2 {
  font-size: 1.05rem;
  font-weight: 650;
  letter-spacing: 0.005em;
  margin-bottom: 0.9rem;
}

/* ---------- theme switch ---------- */

.theme-toggle {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  min-height: 2.5rem;
  padding: 0.45rem 0.85rem;
  font: inherit;
  font-size: 0.85rem;
  font-weight: 600;
  line-height: 1.2;
  color: var(--ink-soft);
  background: var(--surface-alt);
  border: 1px solid var(--line);
  border-radius: 999px;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, transform 0.08s ease;
}

.theme-toggle:hover {
  color: var(--accent-strong);
  border-color: var(--accent-border);
  background: var(--accent-soft);
}

.theme-toggle:active {
  transform: translateY(1px);
}

.theme-toggle:focus-visible {
  outline: 3px solid var(--accent-ring);
  outline-offset: 2px;
}

/* Dark is on: the pill reads as pressed, not just hovered. */
.theme-toggle[aria-pressed="true"] {
  color: var(--accent-strong);
  background: var(--accent-soft);
  border-color: var(--accent-border);
}

/* One icon at a time: the moon offers dark, the sun offers light back. */
.icon.icon-sun {
  display: none;
}

.icon.icon-moon {
  display: block;
}

html[data-theme="dark"] .icon.icon-sun {
  display: block;
}

html[data-theme="dark"] .icon.icon-moon {
  display: none;
}

.theme-toggle-text {
  white-space: nowrap;
}

/* ---------- add-habit form ---------- */

.habit-form {
  display: grid;
  gap: 0.55rem;
}

.field-label {
  display: block;
  font-size: 0.9rem;
  font-weight: 600;
}

.field-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}

.field-input {
  flex: 1 1 14rem;
  min-width: 0;
  min-height: 2.75rem;
  padding: 0.7rem 0.85rem;
  font: inherit;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 0.65rem;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background-color 0.2s ease;
}

.field-input:hover {
  border-color: var(--ink-soft);
}

.field-input:focus-visible {
  outline: 3px solid var(--accent-ring);
  outline-offset: 1px;
  border-color: var(--accent);
}

.field-hint {
  font-size: 0.82rem;
  color: var(--ink-soft);
}

/* ---------- buttons ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  min-height: 2.75rem;
  padding: 0.55rem 0.95rem;
  font: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.2;
  border: 1px solid transparent;
  border-radius: 0.65rem;
  background: var(--accent);
  color: var(--on-accent);
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, transform 0.08s ease;
}

.btn:hover {
  background: var(--accent-strong);
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible {
  outline: 3px solid var(--accent-ring);
  outline-offset: 2px;
}

/* tick button: outlined until the day is ticked, then filled */

.tick-btn {
  background: var(--surface);
  color: var(--accent-strong);
  border-color: var(--accent);
}

.tick-btn:hover {
  background: var(--accent-soft);
}

.tick-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--on-accent);
}

.tick-btn[aria-pressed="true"]:hover {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

/* quiet icon-only button used for delete */

.btn-quiet {
  width: 2.75rem;
  padding: 0.5rem;
  background: transparent;
  border-color: transparent;
  color: var(--ink-soft);
}

.btn-quiet:hover {
  background: var(--surface-alt);
  color: var(--ink);
}

.delete-btn:hover {
  background: var(--danger-soft);
  border-color: transparent;
  color: var(--danger);
}

/* ---------- habit list ---------- */

.habit-list {
  list-style: none;
  padding: 0;
  display: grid;
  gap: 0.7rem;
}

.habit-item {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.9rem;
  padding: 0.85rem 1rem;
  background: var(--item-bg);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  transition: background-color 0.18s ease, border-color 0.18s ease;
}

.habit-item.is-ticked {
  background: var(--accent-soft);
  border-color: var(--accent-border);
}

.habit-info {
  flex: 1 1 auto;
  min-width: 0;
}

.habit-name {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.habit-meta {
  margin-top: 0.2rem;
  font-size: 0.8rem;
  color: var(--ink-soft);
}

.habit-side {
  flex: none;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.5rem;
}

.habit-streak {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink-soft);
  white-space: nowrap;
}

.habit-item.is-ticked .habit-streak {
  color: var(--accent-strong);
}

.habit-actions {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

/* ---------- empty note ---------- */

.empty-note {
  padding: 1.1rem 1rem;
  text-align: center;
  color: var(--ink-soft);
  font-size: 0.9rem;
  background: var(--surface-alt);
  border: 1px dashed var(--line);
  border-radius: var(--radius);
}

.empty-note[hidden] {
  display: none;
}

/* ---------- streak summary ---------- */

.summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8.5rem, 1fr));
  gap: 0.7rem;
}

.summary-item {
  padding: 0.8rem 0.9rem;
  background: var(--surface-alt);
  border-radius: 0.75rem;
}

.summary-item dt {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--ink-soft);
}

.summary-item dd {
  margin-top: 0.15rem;
  font-size: 1.35rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}

#summary-streak {
  font-size: 1.15rem;
}

/* ---------- narrow phones ---------- */

@media (max-width: 34rem) {
  .header-inner {
    flex-direction: column;
    align-items: flex-start;
    gap: 1rem;
  }

  .habit-item {
    flex-direction: column;
    align-items: stretch;
  }

  .habit-side {
    width: 100%;
    align-items: stretch;
  }

  .habit-streak {
    text-align: left;
    white-space: normal;
  }

  .tick-btn {
    flex: 1 1 auto;
  }

  .field-row .btn {
    width: 100%;
  }
}

@media (max-width: 26rem) {
  .summary {
    grid-template-columns: 1fr 1fr;
  }

  .summary-item:last-child {
    grid-column: 1 / -1;
  }
}

/* ---------- motion preferences ---------- */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }

  .btn:active,
  .theme-toggle:active {
    transform: none;
  }
}
